<?php use Tivoli\Domain\Stay\StayRules as R;
if(in_array($case['status'],['draft','revision'],true)):?>
<section class="card"><h2>Prepare Payroll</h2><?php if($case['eligibility_error']):?><p class="error"><?=access_h($case['eligibility_error'])?></p><?php elseif($salary):?><p>Effective Salary: <?=access_h(p_money($salary['base']))?> · Revision #<?=(int)$salary['revision']?> · <?=access_h($salary['payee'].' · '.$salary['wallet'])?></p><p>Review attendance and approved leave separately. No automatic deduction or salary proration is applied.</p>
<form method="post" data-payroll-base="<?=$salary['base']?>" data-confirm="Send these exact payroll amounts for owner review?"><?php p_fields('prepare');?><input type="hidden" name="salary_token" value="<?=access_h($salary['token'])?>">
<div class="payroll-grid"><?php foreach(['allowance'=>'Allowances','overtime'=>'Overtime','deductions'=>'Reviewed Deductions','employer'=>'Employer Costs'] as $n=>$label)p_input($label.' (GHS)',$n,R::decimal($case['prepared'][$n]??0));?></div>
<p data-payroll-preview role="status"></p><?php p_text('Adjustment Explanation','adjustment',false,true);p_text('Internal Comment','comment');p_check('checked','I reviewed effective salary, payee, attendance context and all manual adjustments.');?><button>Prepare For Review</button></form><?php endif?></section>
<?php elseif($case['status']==='review'):?>
<section class="card"><h2>Owner Approval</h2><p>Approval freezes these amounts and records the staff cost in today's open financial period.</p><form method="post" data-confirm="Approve and record this staff cost once?"><?php p_fields('approve');p_text('Approval Reason','reason',true);p_check('authorized','I authorize these exact amounts and the verified staff payment destination.');?><button>Approve Payroll</button></form></section>
<section class="card"><h2>Return For Revision</h2><form method="post" data-confirm="Return this payroll for correction before approval?"><?php p_fields('return');p_text('Revision Reason','reason',true);?><button>Return For Revision</button></form></section>
<?php elseif($case['approved']&&$case['due']>0):?>
<section class="card"><h2>Record Completed MoMo Payment</h2><p>This records a transfer you have already completed. Employee balance: <?=access_h(p_money($case['due']))?>.</p><form method="post" enctype="multipart/form-data" data-confirm="Confirm the actual completed MoMo transfer and record this payment?"><?php p_fields('pay');p_input('Amount (GHS)','amount',R::decimal($case['due']));p_input('Actual Payment Time (UTC)','paid_at',gmdate('Y-m-d\TH:i:s'),'datetime-local');p_input('MoMo Transaction Reference','reference');?><label>Payment Evidence (Optional)<input type="file" name="evidence" accept=".pdf,.png,.jpg,.jpeg"><small>PDF, JPEG or PNG · Maximum 2 MB · Owner Only</small></label><?php p_text('Internal Comment','comment');p_check('verified','I verified the completed transfer, recipient, amount and unique MoMo reference.');?><button>Record Payment</button></form></section>
<?php elseif($case['approved']&&!$case['published_current']&&$case['recovery_due']===0):?>
<section class="card"><h2><?=$case['published']?'Publish Revised Payslip':'Publish Employee Payslip'?></h2><p>The employee balance is settled. Verify the correct active user is linked to this staff record in Staff & HR. Publication is frozen to that account. Deductions and employer remittances are separate.</p><form method="post" data-confirm="Publish this settled statement to the currently linked employee account?"><?php p_fields('publish');?><p>Verified Recipient: <?=access_h($case['recipient']['name'])?></p><input type="hidden" name="recipient_token" value="<?=access_h($case['recipient']['token'])?>"><?php p_check('confirmed','I verified the linked employee account and completed employee settlement.');?><button><?=$case['published']?'Publish Revised Payslip':'Publish Payslip'?></button></form></section>
<?php elseif($case['approved']&&$case['recovery_due']>0):?><section class="card"><h2>Private Overpayment Review</h2><p><?=access_h(p_money($case['recovery_due']))?> remains recorded as overpaid. Resolve the recovery and statement policy before revised publication. Original issued payslips remain available.</p></section><?php endif?>
